SELECT
    (((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30 + 1) AS [c0],
    DATEADD(DAY, 365 * (((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([B1].[v] AS int)) / 13) - 1) + ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([B1].[v] AS int)) / 13) / 4 + 30 * ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([B1].[v] AS int)) % 13) + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([B1].[v] AS int)) % 13) / 12 * (25 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([B1].[v] AS int)) / 13) % 4 / 3))) - (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922), [T].[PostedOn]) AS [c1],
    (((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) / 30) - (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30)) + CASE WHEN ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) / 30) - (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30)) > 0 AND DATEADD(DAY, DATEDIFF(DAY, [T].[PostedOn], [T].[DueOn]) - ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) % 30 + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - (((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) / 30) / 12 * (25 - ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) % 4 / 3))), [T].[PostedOn]) > [T].[DueOn] THEN -1 WHEN ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) / 30) - (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) / 30)) < 0 AND DATEADD(DAY, DATEDIFF(DAY, [T].[PostedOn], [T].[DueOn]) - ((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) % 30 + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[PostedOn]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - (((DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) / 4)) / 30) / 12 * (25 - ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [T].[DueOn]) + 2922) + 1463) / 1461) % 4 / 3))), [T].[PostedOn]) < [T].[DueOn] THEN 1 ELSE 0 END) AS [c2],
    (((DATEDIFF(DAY, CONVERT(date, '00080827'), [B2].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [B2].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [B2].[v]) + 2922) + 1463) / 1461) / 4)) % 30 + 1) AS [c3]
